#!/usr/bin/env python3
"""Actual Python HTTP boundary with disposable data; no worker or model processes."""
from __future__ import annotations

import copy
from http.server import ThreadingHTTPServer
import json
from pathlib import Path
import shutil
import signal
import socket
import sys
import threading
from tempfile import TemporaryDirectory

SOURCE = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(SOURCE))


def seed_workspace(root, project, store, core):
    """Synthetic business documents and call originals, never generated by a model."""
    folder = root / "production" / project["slug"]
    planning = folder / "planning"
    planning.mkdir(parents=True)
    core.write_json(folder / "factory_owner.json", {"project_id": project["id"]})
    (folder / "frames").mkdir()
    shutil.copyfile(SOURCE / "runtime/browser-fixtures/frame.png", folder / "frames/frame.png")
    target = planning / "story-goals.md"
    target.write_text("# 站台上的约定\n\n成年主角与搭档在站台重逢，解释一封迟到的信。\n\n"
                      "|人物|目标|\n|---|---|\n|主角|履行约定|\n|搭档|说清误会|\n\n"
                      "![场景参考](../frames/frame.png)\n\n[分镜原文](storyboard.json)\n\n"
                      + "明确人物动机，保持行动与镜头连续。" * 60, encoding="utf-8")
    script = planning / "script.md"
    script.write_text("# 站台重逢\n\n## 第一场\n\n- 主角拿出旧信。\n- 搭档解释迟到的原因。\n\n**两人决定重新开始。**", encoding="utf-8")
    shots = [{"id": f"S{index + 1:02d}", "seconds": seconds, "dramatic_beat": "解释与行动", "characters": ["char_lead", "char_partner"], "dialogue": [],
              "continuity_state": {"mode": "continuous", "opening_state": "两位成年人站在站台旁，主角拿着旧信。",
                                   "ending_state": "两位成年人仍在站台旁，旧信保持由主角持有。", "allowed_changes": []}}
             for index, seconds in enumerate(project["production_profile"]["shot_seconds"])]
    board = planning / "storyboard.json"
    core.write_json(board, {"shots": shots})
    store.update(project["id"], {"stage": "screenplay", "resolved_story_brief": {"title": "站台上的约定", "goal": "解释误会"},
        "screenplay_draft": None, "script": {"title": "站台重逢", "cast": {"char_lead": "林夏", "char_partner": "陈明"}, "shots": shots},
        "planning_artifacts": {"resolved_story_brief": str(target.relative_to(root)),
                               "screenplay_draft": str(script.relative_to(root)), "storyboard": str(board.relative_to(root))}})
    from factory import team_tasks
    run = team_tasks.begin(project["id"], "screenplay")
    calls = planning / "llm/calls"
    for name, context in (("20261016-screenwriter-current", {"project_id": project["id"], "stage": "screenplay", "run_id": run["run_id"]}),
                          ("20261015-screenwriter-history", None)):
        call = calls / name
        core.write_json(call / "receipt.json", {"role": "screenwriter", "status": "succeeded", "model": "fixture-writer", "execution_context": context, "attempts": [{"attempt": 1}, {"attempt": 2}]})
        for attempt in (1, 2):
            core.write_json(call / f"request-{attempt:02d}.json", {"prompt": "完整输入与人物约束", "messages": [{"role": "user", "content": "编写站台重逢"}], "attempt": attempt})
            core.write_json(call / f"response-{attempt:02d}.json", {"content": "独立浏览器夹具响应", "attempt": attempt})
        core.write_json(call / "parsed.json", {"title": "站台重逢"})
    team_tasks.finish(project["id"], "screenplay", run["run_id"], "succeeded")


def main():
    from factory import environment
    # Stub before importing the web module, which normally loads runtime.env.
    environment.load_environment = lambda *_args, **_kwargs: None
    from studio import core

    # Never discover the operator's private configuration or use live data.
    public_config = json.loads((SOURCE / "config/factory.example.json").read_text())
    with TemporaryDirectory(prefix="drama-http-browser-") as temporary:
        root = Path(temporary)
        shutil.copytree(SOURCE / "ui/factory/dist", root / "ui/factory/dist")
        media = root / "production/http-fixture"
        media.mkdir(parents=True)
        shutil.copyfile(SOURCE / "runtime/browser-fixtures/clip.mp4", media / "clip.mp4")
        core.ROOT = root
        from factory import config
        config.DATA = root / "runtime"
        config.DATABASE = config.DATA / "studio.sqlite3"
        config.CHECKPOINTS = config.DATA / "checkpoints.sqlite3"
        config.load_config = lambda: copy.deepcopy(public_config)
        from factory import store, web
        from studio import web as legacy
        web.snapshot = lambda: {"fixture": True, "models_run": False}

        effects = {"launch_attempts": 0}

        def forbid_launch(_payload):
            effects["launch_attempts"] += 1
            raise RuntimeError("Browser fixture cannot start production")

        # Retired launcher has no implementation. Keep the counter as evidence
        # that cross-origin/retired routes cannot submit production.
        assert not hasattr(legacy, "launch")
        def forbid_outbound(*_args, **_kwargs):
            raise RuntimeError("Browser HTTP fixture forbids outbound connections")

        socket.create_connection = forbid_outbound
        socket.socket.connect = forbid_outbound
        store.initialize()
        project = store.create({"title": "HTTP 边界隔离测试", "brief": "Synthetic HTTP browser fixture; no generation is permitted.",
                                "production_profile": {"preset": "compact6"}})
        seed_workspace(root, project, store, core)
        store.action(project["id"], {"action": "pause"})
        audit_lock = threading.Lock()

        class AuditedHandler(web.Handler):
            def log_request(self, code="-", size="-"):
                # Test-only stdout evidence: CORP deliberately hides rejected
                # cross-origin responses from the browser's response events.
                with audit_lock:
                    print("HTTP_BROWSER_RESPONSE " + json.dumps({
                        "method": self.command, "path": self.path,
                        "status": code, "launch_attempts": effects["launch_attempts"],
                    }), flush=True)

        server = ThreadingHTTPServer(("127.0.0.1", 0), AuditedHandler)
        server.daemon_threads = True
        signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))
        signal.signal(signal.SIGINT, lambda *_: sys.exit(0))
        print("HTTP_BROWSER_FIXTURE_READY " + json.dumps({"port": server.server_port, "project_id": project["id"]}), flush=True)
        try:
            server.serve_forever(poll_interval=.05)
        finally:
            server.server_close()


if __name__ == "__main__":
    main()
